/// kentron: sub-shapes named by OCCT's enumeration are selected by position (draw_selectors.json)
#[test]
fn r8() -> DrawResult<()> {
    let mut d = Draw::new();
    d.pcone(&["c1", "2", "1.5", "5"])?;
    d.profile(&["p", "x", "2", "y", "2", "x", "-2", "y", "-2"])?;
    d.trotate(&["p", "0", "0", "0", "1", "0", "0", "90"])?;
    d.ttranslate(&["p", "-1", "-4", "4"])?;
    d.explode(&["c1", "f"])?;
    d.nearest(&["c1_1", "c1", "F", "6.66134e-16", "2.01094e-17", "2.38095", "55.2521"])?;
    d.mksurface(&["f", "c1_1"])?;
    d.mkface(&["f", "f"])?;
    d.featprism(&["c1", "p", "p", "0", "1", "0", "1", "1"])?;
    d.featperform(&["prism", "result", "f"])?;
    d.checkprops(&["result", "-s", "100.937"])?;
    d.checkshape(&["result"])?;
    Ok(())
}

